class NoteSummarizer:
    def __init__(self, client):
        self.client = client

    def summarize(self, note):
        title = redact(note.title)
        body = note.body  # free text: patient names, phone numbers, diagnoses
        msg = f"Title: {title}\n\n{body}"
        r = self.client.messages.create(model=MODEL, max_tokens=400, system=NOTE_PROMPT,
                                        messages=[{"role": "user", "content": msg}])
        return r.content[0].text

