def _namespace_for(user):
    return f"org-{user.org_id}"

def lookup(user, query):
    ns = _namespace_for(user)
    vec = embed(query)
    res = index.query(vector=vec, top_k=5, include_metadata=True, namespace=DEFAULT_NAMESPACE)
    return {"namespace": ns, "hits": [m.metadata["text"] for m in res.matches]}

def _fetch(url):
    return httpx.get(url, timeout=15, follow_redirects=True).text

def _chunks(html):
    text = html2text.html2text(html)
    return [text[i:i + 900] for i in range(0, len(text), 900)]

def add_reference(user, url):
    store = vector_store_for(user.id)
    store.add_texts(_chunks(_fetch(url)))

class TicketKnowledgeSync:
    def __init__(self, zendesk, store, tenant_id):
        self.zendesk, self.store, self.tenant_id = zendesk, store, tenant_id

    def sync(self, since):
        for ticket in self.zendesk.tickets_updated_since(since):
            for c in ticket.public_comments:  # written by end customers
                self.store.add_texts([c.body], namespace=self.tenant_id)

class TenantRetriever:
    def __init__(self, store):
        self.store = store

    def _filter(self, auth):
        return {"tenant_id": auth.tenant_id}

    def retrieve(self, auth, question, k=5):
        docs = self.store.similarity_search(question, k=k, filter=self._filter(auth))
        return [d.page_content for d in docs]

