class UploadIngestor:
    MAX_BYTES = 2_000_000

    def __init__(self, store_for_user):
        self.store_for_user = store_for_user

    def ingest(self, user, filename, raw: bytes):
        if len(raw) > self.MAX_BYTES or not filename.endswith((".txt", ".md")):
            raise ValueError("rejected upload")
        text = sanitize_text(raw.decode("utf-8"))
        meta = {"source": "upload", "filename": filename, "owner": user.id, "sha256": sha256_hex(raw)}
        chunks = chunk_text(text, 800)
        self.store_for_user(user.id).add_texts(chunks, metadatas=[meta] * len(chunks))
